mcp:tool-listener.mcp:parameters-schema:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "sku": {
      "type": "string",
      "description": "Código SKU del producto a consultar (ej. LAP-001)"
    }
  },
  "required": ["sku"]
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "orderId": {
      "type": "string",
      "description": "Identificador único del pedido (ej. ORD-AI-101)"
    },
    "customerId": {
      "type": "string",
      "description": "Identificador del cliente (ej. CUST-AI-01)"
    },
    "customerName": {
      "type": "string",
      "description": "Nombre completo del cliente"
    },
    "customerEmail": {
      "type": "string",
      "description": "Correo electrónico del cliente"
    },
    "items": {
      "type": "array",
      "description": "Lista de artículos con sku y quantity",
      "items": {
        "type": "object",
        "properties": {
          "sku": { "type": "string" },
          "quantity": { "type": "integer" }
        },
        "required": ["sku", "quantity"]
      }
    }
  },
  "required": ["orderId", "customerId", "customerName", "customerEmail", "items"]
}

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	orderId: payload.orderId default payload.order_id,
	customer: if (payload.customer != null) payload.customer else {
		customerId: payload.customerId default payload.customer_id default "",
		name: payload.customerName default payload.customer_name default "",
		email: payload.customerEmail default payload.customer_email default ""
	},
	items: (payload.items default []) map (item) -> {
		sku: item.sku,
		quantity: item.quantity as Number
	}
}

mcp:tool-listener.mcp:parameters-schema:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "orderId": {
      "type": "string",
      "description": "Identificador de la orden a consultar (ej. ORD-1001)"
    }
  },
  "required": ["orderId"]
}
